function identityIndexMap(){return Array.from({length:256},(_,index)=>index)}
function archiveBankIdentity(target,physicalIndex){return JSON.stringify([String(target?.filename||''),String(target?.byteHash||''),Number(target?.byteLength)||0,physicalIndex===null?'none':Number(physicalIndex)])}
function composeIndexMaps(previous,next){if(!Array.isArray(previous)||previous.length!==256||!Array.isArray(next)||next.length!==256)throw new Error('Palette index maps must contain exactly 256 entries.');return previous.map(index=>next[index])}
function uniqueColorIndices(colors,limit=100){const seen=new Set(),indexes=[];for(let index=0;index<(colors||[]).length&&indexes.length<limit;index++){const color=colors[index];if(!Array.isArray(color))continue;const key=color.slice(0,4).map(value=>Math.max(0,Math.min(255,Number(value)||0))).join(',');if(seen.has(key))continue;seen.add(key);indexes.push(index)}return indexes}
function bankGestureSnapshot(bank,colors,indexMap,selection,workingColor){return{bank,colors:Array.isArray(colors)?colors.map(color=>color.slice()):[],indexMap:bank==='B'&&Array.isArray(indexMap)?indexMap.slice():null,selection:selection?{bank:selection.bank,indices:(selection.indices||[]).slice(),anchor:selection.anchor}:null,workingColor:bank==='A'&&Array.isArray(workingColor)?workingColor.slice():null}}
function bankGestureChanged(before,after){if(!before||!after||before.bank!==after.bank)return false;const flat=value=>(value||[]).flat().join(',');return flat(before.colors)!==flat(after.colors)||flat(before.indexMap)!==flat(after.indexMap)||flat(before.workingColor)!==flat(after.workingColor)}
function recordBankGesture(undo,redo,before,after,limit=30){if(before?.bank!=='B'||!bankGestureChanged(before,after))return false;undo.push(bankGestureSnapshot('B',before.colors,before.indexMap,before.selection,null));if(undo.length>limit)undo.shift();redo.splice(0,redo.length);return true}
function stepBankHistory(from,to,current){if(!from.length)return null;to.push(bankGestureSnapshot('B',current.colors,current.indexMap,current.selection,null));return from.pop()}
function previewBankFromToggle(previewB){return previewB?'B':'A'}
function bankBStageRequest(name,group,number,colors,indexMap){
 const cleanName=String(name||'').trim(),cleanGroup=Number(group),cleanNumber=Number(number);
 if(!cleanName)throw new Error('Give the new Bank B palette a name.');
 if(!Number.isInteger(cleanGroup)||cleanGroup<0||cleanGroup>65535||!Number.isInteger(cleanNumber)||cleanNumber<0||cleanNumber>65535)throw new Error('Choose a whole-number palette group and index from 0 through 65535.');
 if(!Array.isArray(colors)||colors.length!==256||colors.some(color=>!Array.isArray(color)||color.length!==4||color.some(value=>!Number.isInteger(value)||value<0||value>255)))throw new Error('Bank B must contain exactly 256 RGBA colors before it can be staged.');
 if(!Array.isArray(indexMap)||indexMap.length!==256||indexMap.some((value,index)=>!Number.isInteger(value)||value!==index))throw new Error('Bank B has retained index connections. Restore an identity layout or continue through Index Layout & Migration.');
 return{name:cleanName,group:cleanGroup,number:cleanNumber,colors:colors.map(color=>color.slice()),indexMap:indexMap.slice()};
}
function rearrangeBank(colors,selected,destination,offset=true){
 if(!Array.isArray(colors)||colors.length!==256)throw new Error('Bank B must contain exactly 256 colors.');
 const source=[...new Set((selected||[]).map(Number))].filter(Number.isInteger).sort((a,b)=>a-b),start=Number(destination);
 if(!source.length||!Number.isInteger(start)||start<1||start+source.length>256)throw new Error('The selected colors do not fit at that destination.');
 if(source.includes(0))throw new Error('Transparent index 0 cannot be moved.');
 const targets=source.map((_,offsetIndex)=>start+offsetIndex);if(targets.includes(0))throw new Error('Transparent index 0 cannot be replaced.');
 const tagged=colors.map((color,index)=>({color:color.slice(),oldIndex:index}));let arranged;
 if(offset){const moving=tagged.filter(item=>source.includes(item.oldIndex)),remaining=tagged.filter(item=>!source.includes(item.oldIndex));arranged=[...remaining.slice(0,start),...moving,...remaining.slice(start)];}
 else{const origins=identityIndexMap(),sourceSet=new Set(source),targetSet=new Set(targets),displaced=targets.filter(index=>!sourceSet.has(index)).map(index=>origins[index]),vacated=source.filter(index=>!targetSet.has(index));targets.forEach((target,index)=>origins[target]=source[index]);vacated.forEach((target,index)=>origins[target]=displaced[index]);arranged=origins.map(oldIndex=>tagged[oldIndex]);}
 const oldToNew=identityIndexMap();arranged.forEach((item,newIndex)=>oldToNew[item.oldIndex]=newIndex);if(oldToNew[0]!==0)throw new Error('Transparent index 0 cannot be displaced.');
 return{colors:arranged.map(item=>item.color.slice()),oldToNew,selected:source.map(index=>oldToNew[index]),targets};
}

